'use client';
import { useState, useEffect } from 'react';

export default function Home() {
  const [items, setItems] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    // Fetch items from our API
    fetch('/api/items')
      .then(res => res.json())
      .then(data => setItems(data))
      .catch(err => console.error(err));
  }, []);

  const addToCart = (item) => {
    setCart([...cart, item]);
  };

  const handleCheckout = async () => {
    if (cart.length === 0) return alert('장바구니가 비어있습니다.');
    
    // In a real app, integrate Toss Payments here
    const res = await fetch('/api/checkout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ cart }),
    });
    
    const data = await res.json();
    if (data.success) {
      alert('결제가 완료되었습니다. (토스 페이먼츠 연동 준비됨)');
      setCart([]);
    }
  };

  return (
    <div>
      <section className="hero">
        <h1 className="hero-title">Welcome to Palmy</h1>
        <p className="hero-subtitle">Experience our premium services and items.</p>
      </section>

      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '2rem' }}>
        <h2>Available Items</h2>
        <div>
          <button className="btn" onClick={handleCheckout}>
            Checkout ({cart.length} items)
          </button>
        </div>
      </div>

      <div className="grid">
        {items.map((item, index) => (
          <div key={index} className="card">
            <h3>{item.name}</h3>
            <p style={{ color: '#94a3b8', margin: '0.5rem 0' }}>{item.description}</p>
            <p style={{ fontWeight: 'bold', marginBottom: '1rem', color: '#10b981' }}>{item.price.toLocaleString()} 원</p>
            <button className="btn" onClick={() => addToCart(item)} style={{ width: '100%' }}>
              Add to Cart
            </button>
          </div>
        ))}
        {items.length === 0 && (
          <p>No items available. Admin needs to add them!</p>
        )}
      </div>
    </div>
  );
}
